    public static final String DECK_SOURCE="mesh/carrier_running_deck_r52.json",DECK_SHA="6708e3a6db4396721b857121acddf75baab5af8d35455c33af5a8b2e5e2454ce";
    public static final double FIT=.0002,MAX_DROP=5.40;
    public record Joint(double drop,double pitch,double yaw){public Joint(double drop,double pitch){this(drop,pitch,0);}public Joint{if(!Double.isFinite(drop)||drop<0||drop>MAX_DROP||!Double.isFinite(pitch)||Math.abs(pitch)>Math.PI/2+1e-8||!Double.isFinite(yaw))throw new IllegalArgumentException("Real bounded slide and independent capture hinges required");}}
    public record RidePose(List<Joint> joints,boolean captured){public RidePose(List<Joint> joints){this(joints,false);}public RidePose{joints=List.copyOf(joints);if(joints.size()!=4)throw new IllegalArgumentException("Four original housing shoes required");}}
    public record Piece(String name,NervRigidMeshSweepR52 mesh,double[] rgb,RigidTransform frame,String role){}
    public record Surface(String part,Vec3 point,Vec3 normal){}
    public record LeadSampleR52(NervServiceFootDriveR52.Spec spec,float serviceBridge,float rise,long at){public LeadSampleR52{Objects.requireNonNull(spec);if(!Float.isFinite(serviceBridge)||serviceBridge<0||serviceBridge>1||!Float.isFinite(rise)||rise<0||rise>1)throw new IllegalArgumentException("Actual service gantry clocks required");}}
    public record PadBearing(String shoe,int probes,double area,double maximumFit,double minimumUpwardNormal){public boolean bears(){return probes>=3&&area>=.0025&&maximumFit<=FIT&&minimumUpwardNormal>.8;}}
    private record Template(double[] rgb,NervRigidMeshSweepR52 mesh,String role,String frame,RigidTransform drawFrame){}
    private record HeadTriangle(String part,Vec3 a,Vec3 b,Vec3 c,Vec3 normal){}
    private static final Map<Long,List<HeadTriangle>> headCells=new HashMap<>();
    private static Map<String,Template> templates;private static RigidTransform originalFrame;private static NervRigidMeshSweepR52 deck;
    private static long cell(int x,int z){return ((long)x<<32)^(z&0xffffffffL);}
    private static byte[] checked(String path,String hash)throws IOException{var b=EvaOriginalMeshGeometryR52.classpathBytes(path);try{if(!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b)).equals(hash))throw new IllegalStateException("Actual running-head/deck source changed");}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}return b;}
    private static Vec3 point(JsonArray a){return new Vec3(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble());}
